<template>
<section class="ha-panel hs-panel">
  <header class="hs-header"><div><span class="ha-eyebrow">HEALTH INTELLIGENCE · 香港</span><h2>Service demand & surveillance <small>醫院服務需求 · 流感 · 急症傳染病症狀監測</small></h2></div><v-select v-model="weeks" :items="[13,26,52]" label="Trend window · weeks" density="compact" variant="outlined" hide-details></v-select></header>
  <p v-if="error" class="hs-alert" role="status">{{ error }} · Showing last available data where present.</p>
  <div class="hs-status"><span v-for="s in sources" :key="s.key" :class="{old:old(s.key)}">{{ s.label }} <b>{{ doc(s.key)?.latest || 'Unavailable' }}</b><em>{{ old(s.key)?'Historical / delayed':s.cadence }}</em></span></div>
  <div class="hs-columns">
    <article class="hs-block">
      <div class="hs-title"><h3>01 / Hospital service demand</h3><span>Daily during surge periods</span></div>
      <p v-if="old('surge')" class="hs-alert">Latest published surge-period data; does not describe today's hospital load.</p>
      <div class="hs-kpis"><div v-for="m in demandMetrics.slice(0,3)" :key="m.key"><small>{{ m.label }}</small><strong>{{ fmt(overall?.[m.key],m.unit) }}</strong><span>{{ change(overall?.[m.key],previousOverall?.[m.key],m.unit) }} vs prior day</span></div></div>
      <div class="hs-controls"><v-select v-model="demandMetric" :items="demandMetrics.map(m=>({title:m.label,value:m.key}))" label="Hospital comparison" density="compact" variant="outlined" hide-details></v-select><v-select v-model="region" :items="['All clusters',...regions]" label="Cluster" density="compact" variant="outlined" hide-details></v-select></div>
      <div class="hs-chart" v-if="demandTrend.length"><div class="hs-caption">HA overall · last 28 published days · {{ selectedDemand.unit || 'people' }}</div><svg viewBox="0 0 420 124" role="img" :aria-label="selectedDemand.label+' trend'"><g v-for="tick in [0,0.5,1]" :key="tick"><line x1="38" x2="410" :y1="92-tick*76" :y2="92-tick*76"/><text x="2" :y="96-tick*76">{{ fmt(chart(demandTrend,demandMetric).max*tick) }}</text></g><path :d="chart(demandTrend,demandMetric).path" class="hs-line"/><text x="38" y="116">{{ demandTrend[0]?.date }}</text><text x="410" y="116" text-anchor="end">{{ demandTrend.at(-1)?.date }}</text></svg></div>
      <div class="hs-rank"><table><thead><tr><th>Hospital</th><th>{{ selectedDemand.unit==='%'?'Occupancy %':'People' }}</th><th>Δ day</th></tr></thead><tbody><tr v-for="r in hospitals" :key="r.hospital"><th :title="r.cluster">{{ r.hospital }}<div class="hs-track"><i :class="{over:selectedDemand.unit==='%'&&r[demandMetric]>100}" :style="{width:bar(r[demandMetric],rankMax)+'%'}"></i><b v-if="selectedDemand.unit==='%'" :style="{left:100/rankMax*100+'%'}"></b></div></th><td>{{ fmt(r[demandMetric],selectedDemand.unit) }}</td><td>{{ hospitalDelta(r) }}</td></tr></tbody></table></div>
      <p class="ha-note">Sorted by selected metric. Occupancy can exceed 100%; marker = 100%. HA overall uses the published aggregate, not a mean of hospital rates. Missing values are —.</p>
    </article>
    <article class="hs-block">
      <div class="hs-title"><h3>02 / Influenza activity</h3><span>Weekly · laboratory & hospital</span></div>
      <div class="hs-kpis"><div><small>Specimen positivity</small><strong>{{ fmt(fluLatest?.AandB_proportion==null?null:fluLatest.AandB_proportion*100,'%') }}</strong><span>{{ change(fluLatest?.AandB_proportion==null?null:fluLatest.AandB_proportion*100,fluPrevious?.AandB_proportion==null?null:fluPrevious.AandB_proportion*100,'%') }} vs prior week</span></div><div><small>School outbreaks</small><strong>{{ fmt(fluLatest?.ILI_School) }}</strong><span>{{ change(fluLatest?.ILI_School,fluPrevious?.ILI_School) }} vs prior week</span></div><div><small>All-age admissions</small><strong>{{ fmt(fluLatest?.Adm_All) }}</strong><span>per 10,000 population</span></div></div>
      <div class="hs-caption">Influenza A/B positivity · % of respiratory specimens</div>
      <svg v-if="fluTrend.length" viewBox="0 0 420 124" role="img" aria-label="Weekly influenza specimen positivity"><g v-for="tick in [0,0.5,1]" :key="tick"><line x1="38" x2="410" :y1="92-tick*76" :y2="92-tick*76"/><text x="2" :y="96-tick*76">{{ fmt(chart(fluTrend,'positivity').max*tick) }}</text></g><path :d="chart(fluTrend,'positivity').path" class="hs-line purple"/><text x="38" y="116">{{ fluTrend[0]?.date }}</text><text x="410" y="116" text-anchor="end">{{ fluTrend.at(-1)?.date }}</text></svg>
      <div class="hs-flu-composition">
        <div class="hs-latest-mix">
          <div class="hs-caption">Latest typed detections · 最新分型構成</div>
          <svg class="hs-donut" viewBox="0 0 160 160" role="img" :aria-label="virusMixLabel">
            <circle cx="80" cy="80" r="58" fill="none" stroke="#edf2f4" stroke-width="20"/>
            <template v-if="virusMix.total>0"><circle v-for="part in virusMix.parts.filter(p=>p.value>0)" :key="part.key" cx="80" cy="80" r="58" fill="none" :stroke="part.color" stroke-width="20" pathLength="100" :stroke-dasharray="`${part.share} ${100-part.share}`" :stroke-dashoffset="-part.offset" transform="rotate(-90 80 80)"><title>{{ part.label }}: {{ fmt(part.value) }} · {{ fmt(part.share,'%') }}</title></circle></template>
            <text class="hs-donut-total" x="80" y="79" text-anchor="middle">{{ virusMix.complete?fmt(virusMix.total):'—' }}</text>
            <text class="hs-donut-unit" x="80" y="98" text-anchor="middle">H1 + H3 + B</text>
          </svg>
          <dl class="hs-mix-legend"><div v-for="part in virusMix.parts" :key="part.key"><dt><i :style="{background:part.color}"></i>{{ part.label }}</dt><dd>{{ fmt(part.value) }} <span>{{ virusMix.total>0?fmt(part.share,'%'):'—' }}</span></dd></div></dl>
          <p v-if="!virusMix.complete" class="ha-note" role="status">Subtype data incomplete; composition unavailable.</p>
          <p v-else-if="virusMix.total===0" class="ha-note" role="status">No detections in the three listed subtypes.</p>
        </div>
        <div class="hs-mix-history">
      <div class="hs-caption">Positive detections · last 12 weeks <span class="hs-legend"><i v-for="(v,i) in viruses" :key="v" :style="{color:virusColors[i]}">● {{ v }}</i></span></div>
      <svg viewBox="0 0 420 116" role="img" aria-label="Weekly positive influenza detections by virus subtype"><g v-for="(r,i) in virusRows" :key="r.date"><rect v-for="(v,j) in viruses" :key="v" :x="38+i*31" :y="90-virusHeight(r,j,true)" width="20" :height="virusHeight(r,j,false)" :fill="virusColors[j]"><title>{{ r.date }} · {{ v }}: {{ fmt(r[v]) }}</title></rect></g><text x="2" y="18">{{ fmt(virusMax) }}</text><text x="2" y="94">0</text><text x="38" y="111">{{ virusRows[0]?.date }}</text><text x="410" y="111" text-anchor="end">{{ virusRows.at(-1)?.date }}</text></svg>
        </div>
      </div>
      <p class="ha-note">{{ fluLatest?.start || '—' }} – {{ fluLatest?.date || '—' }} · Shares use H1 + H3 + B detections only; these may differ from total influenza A/B positives.</p>
      <div class="hs-caption">Latest influenza admission rate by age · per 10,000 in age group</div>
      <div class="hs-age" v-for="a in ages" :key="a.key"><span>{{ a.label }}</span><div class="hs-track"><i :style="{width:bar(fluLatest?.[a.key],ageMax)+'%'}"></i></div><b>{{ fmt(fluLatest?.[a.key]) }}</b></div>
      <p class="ha-note">Week {{ fluLatest?.start || '—' }} – {{ fluLatest?.date || '—' }}. Positive detections are counts; positivity is a specimen proportion. Blank subtype counts are not treated as zero.</p>
    </article>
  </div>
  <article class="hs-block hs-aed"><div class="hs-title"><h3>03 / A&E syndromic surveillance</h3><span>Weekly · per 1,000 coded consultations · independent scales</span></div>
    <div class="hs-small-multiples"><div v-for="m in syndromes" :key="m.key"><h4>{{ m.label }}</h4><strong>{{ fmt(aedLatest?.[m.key]) }}</strong><span class="hs-delta">{{ change(aedLatest?.[m.key],aedPrevious?.[m.key]) }} vs prior week</span><svg v-if="aedTrend.length" viewBox="0 0 420 124" role="img" :aria-label="m.label+' weekly rate'"><g v-for="tick in [0,0.5,1]" :key="tick"><line x1="38" x2="410" :y1="92-tick*76" :y2="92-tick*76"/><text x="2" :y="96-tick*76">{{ fmt(chart(aedTrend,m.key).max*tick) }}</text></g><path :d="chart(aedTrend,m.key).path" class="hs-line"/><text x="38" y="116">{{ aedTrend[0]?.date }}</text><text x="410" y="116" text-anchor="end">{{ aedTrend.at(-1)?.date }}</text></svg></div></div>
    <p class="ha-note">Based on diagnosis codes and symptom groups, not laboratory-confirmed infection counts. Provisional and subject to revision. Week {{ aedLatest?.start || '—' }} – {{ aedLatest?.date || '—' }}.</p>
  </article>
  <footer class="hs-footer"><span>Sources: <a v-for="s in sources" :key="s.key" :href="s.url" target="_blank" rel="noopener noreferrer">{{ s.label }}</a></span><span>Reporting dates above · Daily source checks · Gaps remain gaps</span></footer>
</section>
</template>
<script>
export default {
 data(){return {documents:{},errors:{},weeks:26,region:'All clusters',demandMetric:'med_bed_occ_rate',now:Date.now(),timer:null,
 sources:[{key:'surge',label:'HA demand',cadence:'Surge-period daily',url:'https://data.gov.hk/en-data/dataset/hospital-hadata-key-statistics-during-surge'},{key:'flu',label:'CHP influenza',cadence:'Weekly',url:'https://data.gov.hk/en-data/dataset/hk-dh-chpsebcddr-flu-express'},{key:'aed',label:'CHP A&E syndromes',cadence:'Weekly',url:'https://data.gov.hk/en-data/dataset/hk-dh-chpsebcdde-aed-cdis-syndromic'}],
 demandMetrics:[{key:'ae_first_attend',label:'A&E first attendances',unit:''},{key:'ae_to_med_ip',label:'A&E → medical admission',unit:''},{key:'med_bed_occ_rate',label:'Medical bed occupancy',unit:'%'},{key:'ped_bed_occ_rate',label:'Paediatric bed occupancy',unit:'%'}],
 viruses:['H1','H3','B'],virusColors:['#7462be','#169b9c','#db9a3b'],ages:[{key:'Adm_0_5',label:'0–5'},{key:'Adm_6_11',label:'6–11'},{key:'Adm_12_17',label:'12–17'},{key:'Adm_18_49',label:'18–49'},{key:'Adm_50_64',label:'50–64'},{key:'Adm_65_higher',label:'65+'}],
 syndromes:[{key:'ili_weekly_average_rate',label:'Influenza-like illness · 流感樣疾病'},{key:'hfmd_weekly_average_rate',label:'Hand, foot & mouth · 手足口病'},{key:'age_weekly_average_rate',label:'Acute gastroenteritis · 急性腸胃炎'},{key:'acj_weekly_average_rate',label:'Acute conjunctivitis · 急性結膜炎'}]}},
 mounted(){this.send({topic:'ha-health-request'});this.timer=setInterval(()=>{this.now=Date.now()},60000)},unmounted(){clearInterval(this.timer)},
 watch:{msg:{immediate:true,handler(msg){if(msg?.topic==='ha-health-error'){this.errors=msg.errors||{database:msg.payload};return}if(msg?.topic!=='ha-health-data')return;for(const d of msg.payload||[]){const prev=this.documents[d.source];if(d.rows?.length&&(!prev||d.latest>prev.latest||d.latest===prev.latest&&d.fetchedAt>=prev.fetchedAt))this.documents[d.source]=d}if(msg.errors)this.errors=msg.errors}}},
 computed:{
 error(){return Object.values(this.errors).join(' · ')},
 overallRows(){return this.rows('surge').filter(r=>r.cluster==='HA Overall'&&!r.hospital)},overall(){return this.overallRows.at(-1)},previousOverall(){const a=this.overallRows;return a.length>1&&this.consecutive(a.at(-1),a.at(-2),1)?a.at(-2):null},
 selectedDemand(){return this.demandMetrics.find(m=>m.key===this.demandMetric)},regions(){return [...new Set(this.rows('surge').filter(r=>r.date===this.doc('surge')?.latest&&r.hospital).map(r=>r.cluster))].sort()},
 hospitals(){return this.rows('surge').filter(r=>r.date===this.doc('surge')?.latest&&r.hospital&&(this.region==='All clusters'||r.cluster===this.region)).sort((a,b)=>(b[this.demandMetric]??-1)-(a[this.demandMetric]??-1))},
 rankMax(){return Math.max(this.selectedDemand.unit==='%'?120:1,...this.hospitals.map(r=>r[this.demandMetric]||0))},demandTrend(){return this.overallRows.slice(-28)},
 fluTrend(){return this.rows('flu').slice(-this.weeks).map(r=>({...r,positivity:r.AandB_proportion==null?null:r.AandB_proportion*100}))},fluLatest(){return this.rows('flu').at(-1)},fluPrevious(){const a=this.rows('flu');return a.length>1&&this.consecutive(a.at(-1),a.at(-2),7)?a.at(-2):null},
 virusMix(){
   const complete=this.viruses.every(key=>Number.isFinite(this.fluLatest?.[key])&&this.fluLatest[key]>=0);
   const total=complete?this.viruses.reduce((sum,key)=>sum+this.fluLatest[key],0):null;
   let offset=0;const parts=this.viruses.map((key,i)=>{const value=this.fluLatest?.[key]??null,share=total>0?value/total*100:null;const part={key,label:key==='B'?'B':`A(${key})`,color:this.virusColors[i],value,share,offset};offset+=share||0;return part});
   return {complete,total,parts};
 },
 virusMixLabel(){return `Typed influenza detections, ${this.fluLatest?.start||'unknown'} to ${this.fluLatest?.date||'unknown'}: `+(this.virusMix.complete?this.virusMix.parts.map(p=>`${p.label} ${this.fmt(p.value)}, ${this.virusMix.total>0?this.fmt(p.share,'%'):'no share'}`).join('; '):'incomplete subtype data')},
 virusRows(){return this.rows('flu').slice(-12)},virusMax(){return Math.max(1,...this.virusRows.map(r=>this.viruses.every(v=>r[v]!=null)?this.viruses.reduce((s,v)=>s+r[v],0):0))},ageMax(){return Math.max(1,...this.ages.map(a=>this.fluLatest?.[a.key]||0))},
 aedTrend(){return this.rows('aed').slice(-this.weeks)},aedLatest(){return this.rows('aed').at(-1)},aedPrevious(){const a=this.rows('aed');return a.length>1&&this.consecutive(a.at(-1),a.at(-2),7)?a.at(-2):null}
 },
 methods:{doc(s){return this.documents[s]},rows(s){return this.doc(s)?.rows||[]},old(s){return !this.doc(s)||this.now-Date.parse(this.doc(s).latest+'T23:59:59+08:00')>(s==='surge'?3:14)*86400000},fmt(n,u=''){return n==null||!Number.isFinite(n)?'—':new Intl.NumberFormat('en-GB',{maximumFractionDigits:2}).format(n)+u},change(a,b,u=''){return a==null||b==null?'—':`${a-b>0?'+':''}${this.fmt(Number((a-b).toFixed(3)))}${u==='%'?' pp':''}`},consecutive(a,b,days){return Date.parse(a.date)-Date.parse(b.date)===days*86400000},bar(n,max){return n==null?0:Math.max(0,Math.min(100,n/max*100))},
 hospitalDelta(r){const p=this.rows('surge').find(p=>p.hospital===r.hospital&&p.cluster===r.cluster&&Date.parse(r.date)-Date.parse(p.date)===86400000);return this.change(r[this.demandMetric],p?.[this.demandMetric],this.selectedDemand.unit)},
 virusHeight(r,j,cumulative){if(!this.viruses.every(v=>r[v]!=null))return 0;return (cumulative?this.viruses.slice(0,j+1).reduce((s,v)=>s+r[v],0):r[this.viruses[j]])/this.virusMax*76},
 chart(rows,key){const max=Math.max(1,...rows.map(r=>r[key]??0));const start=Date.parse(rows[0]?.date),span=Math.max(1,Date.parse(rows.at(-1)?.date)-start);let path='',prev=null;const days=key.includes('weekly')||key==='positivity'?7:1;for(const r of rows){if(r[key]==null){prev=null;continue}const x=38+(Date.parse(r.date)-start)/span*372,y=92-r[key]/max*76;path+=(prev&&Date.parse(r.date)-Date.parse(prev.date)<=days*86400000?'L':'M')+x.toFixed(2)+','+y.toFixed(2)+' ';prev=r}return {path,max}}
 }
}
</script>
<style>
.hs-panel{padding:22px}.hs-header{display:flex;justify-content:space-between;align-items:center;gap:24px}.hs-header .v-input{max-width:180px}.hs-header h2{margin-bottom:8px}.hs-status{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0 18px}.hs-status>span{font-size:11px;border:1px solid #dce8e7;background:#f2f8f7;border-radius:6px;padding:6px 10px}.hs-status b{margin:0 8px;font-variant-numeric:tabular-nums}.hs-status em{font-style:normal;color:#617580}.hs-status .old{background:#fff6e8;border-color:#efd4aa}.hs-columns{display:grid;grid-template-columns:1.15fr 1fr;gap:16px}.hs-block{border:1px solid var(--ha-border);border-radius:10px;padding:16px;min-width:0}.hs-title{display:flex;justify-content:space-between;align-items:baseline;gap:12px;margin-bottom:12px}.hs-title h3{font-size:14px;margin:0}.hs-title>span,.hs-caption{font-size:10px;color:var(--ha-muted)}.hs-kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;border-bottom:1px solid var(--ha-border);padding-bottom:12px;margin-bottom:14px}.hs-kpis>div{display:flex;flex-direction:column}.hs-kpis small{font-size:10px;color:var(--ha-muted)}.hs-kpis strong{font-size:25px;letter-spacing:-1px;font-variant-numeric:tabular-nums}.hs-kpis span{font-size:10px;color:var(--ha-muted)}.hs-controls{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px}.hs-panel svg{display:block;width:100%;overflow:visible}.hs-panel svg line{stroke:#e5ebee;stroke-width:1}.hs-panel svg text{font-size:9px;fill:#617580}.hs-panel .hs-line{fill:none;stroke:#087e8b;stroke-width:2;stroke-linejoin:round}.hs-panel .hs-line.purple{stroke:#7462be}.hs-caption{margin:12px 0 4px}.hs-legend{float:right;display:flex;gap:8px}.hs-legend i{font-style:normal}.hs-rank{max-height:370px;overflow:auto;margin-top:8px}.hs-rank table{border-collapse:collapse;width:100%;font-size:11px}.hs-rank thead{position:sticky;top:0;background:white;z-index:1}.hs-rank th{text-align:left;font-weight:500}.hs-rank td{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}.hs-rank th,.hs-rank td{padding:7px 5px;border-bottom:1px solid #edf1f3}.hs-rank th:first-child{width:72%}.hs-track{position:relative;height:5px;background:#edf2f4;border-radius:2px;margin-top:4px;overflow:hidden}.hs-track i{display:block;height:100%;background:#168d95}.hs-track i.over{background:#c17c26}.hs-track b{position:absolute;top:0;height:100%;border-left:1px solid #6b4a1d}.hs-age{display:grid;grid-template-columns:45px 1fr 45px;gap:10px;align-items:center;font-size:11px;margin-top:8px}.hs-age b{text-align:right;font-weight:500}.hs-age .hs-track i{background:#7462be}.hs-aed{margin-top:16px}.hs-small-multiples{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.hs-small-multiples h4{font-size:11px;font-weight:500;margin:0 0 5px}.hs-small-multiples strong{font-size:24px;font-variant-numeric:tabular-nums}.hs-delta{display:block;font-size:10px;color:var(--ha-muted)}.hs-panel .hs-alert{font-size:11px;color:#89602c;background:#fff6e8;padding:7px 10px;border-radius:4px;margin-bottom:12px}.hs-footer{display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px;font-size:10px;color:var(--ha-muted);margin-top:12px}.hs-footer a{margin-left:10px}.hs-panel .ha-note{font-size:10px;margin:10px 0 0}@media(max-width:1050px){.hs-columns{grid-template-columns:1fr}.hs-small-multiples{grid-template-columns:repeat(2,1fr)}}@media(max-width:550px){.hs-panel{padding:12px}.hs-header{align-items:flex-start;gap:10px}.hs-header .v-input{min-width:120px}.hs-title{display:block}.hs-controls{grid-template-columns:1fr}.hs-small-multiples{grid-template-columns:1fr}.hs-kpis strong{font-size:21px}}
/* Latest composition and history share the same subtype colours. */
.hs-flu-composition{display:grid;grid-template-columns:minmax(140px,.8fr) minmax(0,1.2fr);gap:16px;align-items:center;margin-top:8px}.hs-latest-mix{min-width:0}.hs-panel .hs-donut{width:140px;max-width:100%;margin:4px auto}.hs-panel .hs-donut-total{font-size:25px;font-weight:600;fill:#203642;font-variant-numeric:tabular-nums}.hs-panel .hs-donut-unit{font-size:10px}.hs-mix-legend{margin:0;font-size:10px}.hs-mix-legend>div{display:flex;justify-content:space-between;gap:8px;margin:5px 0}.hs-mix-legend dt{white-space:nowrap}.hs-mix-legend dt i{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:5px}.hs-mix-legend dd{margin:0;font-variant-numeric:tabular-nums;white-space:nowrap}.hs-mix-legend dd span{display:inline-block;min-width:50px;text-align:right;color:var(--ha-muted)}.hs-mix-history{min-width:0}.hs-mix-history .hs-legend{float:none;margin-top:4px}.hs-mix-history svg text{font-size:13px}@media(max-width:550px){.hs-flu-composition{grid-template-columns:1fr}.hs-latest-mix{max-width:240px;margin:auto;width:100%}}
</style>
